import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"SMAWK 决策单调","description":"","frontmatter":{"title":"SMAWK 决策单调","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/smawk.md","filePath":"cs/smawk.md","lastUpdated":1789023840000}'),h={name:"cs/smawk.md"};function A(m,a,_,M,S,u){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="smawk-决策单调" tabindex="-1">SMAWK 决策单调 <a class="header-anchor" href="#smawk-决策单调" aria-label="Permalink to &quot;SMAWK 决策单调&quot;">​</a></h1><div class="epigraph"><p>完全单调矩阵每行最小值的列号非降；SMAWK 用减治在 $O(n)$ 次查询内找出所有行最小（列数同类）。</p><footer>—— 据 Aggarwal, Klawe, Moran, Shor and Wilber, Geometric Applications of a Matrix-Searching Algorithm, 1987 整理</footer></div><p>上一课<a href="/cs/dc-opt-quadrangle">分治优化与四边形不等式</a>已用 \\(opt\\) 单调做分治 \\(O(n\\log n)\\)。更强：矩阵 \\(A[i,j]=dp[j]+w(j,i)\\) 完全单调时，SMAWK 线性求每行 \\(\\arg\\min\\)。缺口是这份减治，不是再证四边形。后课插头 DP 换网格轮廓。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>矩阵 \\(M\\) 完全单调：对 \\(a\\lt b\\)，\\(c\\lt d\\)，若 \\(M(a,c)\\gt M(a,d)\\) 则 \\(M(b,c)\\gt M(b,d)\\)（行最小位置非降的充分结构）。SMAWK：奇偶行减列，递归。查询 \\(M(i,j)\\) 若 \\(O(1)\\)，总时间 \\(O(n)\\)（\\(n\\times n\\)）。</p><p>DP 一层：\\(dp&#39;[i]=\\min_j dp[j]+w(j,i)\\) 可一次 SMAWK。比分治少 \\(\\log\\)。</p><h3 id="不是任意单调队列" tabindex="-1">不是任意单调队列 <a class="header-anchor" href="#不是任意单调队列" aria-label="Permalink to &quot;不是任意单调队列&quot;">​</a></h3><p>完全单调强于「每行最小非降」的使用方式，实现细节多。不会证 \\(w\\) 就不要宣称 SMAWK。实践多分治够用。</p><p><span class="marginnote">Aggarwal 等 1987（作者姓首字母 SMAWK）。后课插头 DP 是另一指数状态，不是矩阵搜索。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>若 \\(w\\) 使 \\(M\\) 完全单调，调用 SMAWK 得 \\(opt[i]\\)，再填 \\(dp\\)。实现可先写分治，SMAWK 当加速。</p>',11)),(e(),s(c,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%AE%8C%E5%85%A8%E5%8D%95%E8%B0%83%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20SM%5B%22SMAWK%20%E5%87%8F%E6%B2%BB%22%5D%0A%20%20SM%20--%3E%20OPT%5B%22%E6%AF%8F%E8%A1%8C%20argmin%22%5D%0A%20%20OPT%20--%3E%20DP%5B%22%E4%B8%80%E5%B1%82%20DP%20%E7%BA%BF%E6%80%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>查询复杂度乘进总时间。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>减列：比较相邻，劣列永不做某奇偶行的最小。递归规模减半。与四边形：四边形常推出完全单调，细节依赖 \\(w\\)。与 CHT：CHT 要直线结构，SMAWK 要矩阵单调。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不手写 SMAWK 全伪代码。不写高维。后课默认：决策单调先分治；完全单调可 SMAWK。下一课插头 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完全单调 \\(\\Rightarrow\\) 行最小线性可求。</li><li>DP 一层可 \\(O(n)\\) 查询级。</li><li>结构比分治更苛刻。</li><li>出处：Aggarwal, Klawe, Moran, Shor and Wilber, 1987。</li></ul>',7))])}const g=o(h,[["render",A]]);export{P as __pageData,g as default};
